    /// Optional images attached to the turn (OCEAN-115). When present, the daemon
    /// emits one `Content::Image` block per entry alongside the prompt text on the
    /// FIRST user message of the turn, enabling vision end-to-end. Existing clients
    /// that don't send this are unaffected (`#[serde(default)]` → `None`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub images: Option<Vec<TurnImage>>,
    /// Per-turn secret binding the permission gate to THIS submitter (OCEAN-185,
    /// P0). The client mints a high-entropy token (see
    /// `ocean_core::mint_decision_token`) and sends it here; the daemon binds it
    /// to the turn and every `PermissionRequest` the turn raises, but NEVER echoes
    /// it on the unauthenticated `/v1/events` SSE. The decision POST must replay
    /// the same token or the daemon returns 403 — closing the bypass where a
    /// localhost page sniffs the broadcast `permission_id` and approves a gated
    /// tool. `None` (legacy clients) leaves the turn's gate unbound.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub decision_token: Option<String>,
    /// Phase-2 client/browser context (OCEAN-40). When the surface is an
    /// in-browser one (`client_type == "surface-extension"`), it ships the
    /// active-tab url/title (and optionally the full tab list) here so the agent
    /// can see what's loaded without a round-trip. Additive + optional: every
    /// existing client omits it (the flat `client_type` field above is untouched
    /// and remains the back-compat surface selector), so old payloads still
    /// deserialize and other `client_type`s are unaffected.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub client_context: Option<ClientContext>,
    /// Per-turn override for the post-turn advisor observer. When present it
    /// wins over the daemon's global `[roles].advisor` config for THIS turn:
    /// `enabled:false` suppresses the advisor even if a global role is set;
    /// `enabled:true` runs it on `model` (or the global advisor role when
    /// `model` is `None`). `None` (every existing client) leaves the global
    /// advisor behavior untouched. Lets a surface toggle the second-opinion
    /// reviewer per session without editing `ocean.toml` + restarting.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub advisor: Option<AdvisorControl>,
}

